WITH filtered_order_items AS (SELECT * FROM order_items WHERE order_id = 23), agg AS (SELECT CASE WHEN quantity >= 9 THEN 'high' WHEN quantity >= 2 THEN 'mid' ELSE 'low' END AS quantity_bucket, MIN(quantity) AS min_quantity FROM filtered_order_items GROUP BY CASE WHEN quantity >= 9 THEN 'high' WHEN quantity >= 2 THEN 'mid' ELSE 'low' END) SELECT quantity_bucket, min_quantity FROM agg
